-- food menu snapshots, batch 3 (25 menus)
with target as (
  select slug from venues where slug = 'koa-shala-sanur' and status = 'active' and publication_status = 'published'
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Yoga Schedule', 1, 'draft', 'partial', 'https://www.koashala.com/yoga', 'Official Koa Shala menu',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, 'ee226fa3617d34f67fff2cf0b9ee8a1ee083df919a2f0430f53cc3d0a56d7cea', 'food'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'food')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Weekly Schedule', 0), ('Pricing', 1)) as s(name, pos)
  returning id, name
)
insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Weekly Schedule', 'Vinyasas', null, null, null, 0), ('Weekly Schedule', 'Morning Flow', null, null, null, 1), ('Weekly Schedule', 'Yin Yang', null, null, null, 2), ('Weekly Schedule', 'Mindfull Yin', null, null, null, 3), ('Weekly Schedule', 'Hatha Flow', null, null, null, 4), ('Weekly Schedule', 'Vinyasa', null, null, null, 5), ('Weekly Schedule', 'Hatha Yoga', null, null, null, 6), ('Weekly Schedule', 'Vinyasa All Level', null, null, null, 7), ('Weekly Schedule', 'Gentle Yoga', null, null, null, 8), ('Weekly Schedule', 'Power Yoga 45 Mins', null, null, null, 9), ('Weekly Schedule', 'Kundalini', null, null, null, 10), ('Weekly Schedule', 'Creative Vinyasa 45 Mins', null, null, null, 11), ('Weekly Schedule', 'Unwind & Restore : Yin Yoga', null, null, null, 12), ('Weekly Schedule', 'Meditation & Mindful 60 Mins', null, null, null, 13), ('Weekly Schedule', 'Ashtanga', null, null, null, 14), ('Weekly Schedule', 'Mat Pilates', null, null, null, 15), ('Weekly Schedule', 'Yoga Classes', null, null, null, 16), ('Pricing', 'Casual class', 'Single class entry', 120000, 'IDR', 0), ('Pricing', 'Karma club member', 'Discounted price for members', 90000, 'IDR', 1), ('Pricing', 'Yoga 45 Minute', '45 minute class', 70000, 'IDR', 2), ('Pricing', '5 Class concession', 'Package of 5 classes', 550000, 'IDR', 3), ('Pricing', '10 Class concession', 'Package of 10 classes', 1000000, 'IDR', 4), ('Pricing', '20 Class concession', 'Package of 20 classes', 1600000, 'IDR', 5), ('Pricing', 'Yoga Class + 60 Minute treatment', 'Includes Body Massage or Feet Reflexology', 380000, 'IDR', 6), ('Pricing', 'Yoga Class + 90 minutes Body Massage', null, 500000, 'IDR', 7)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

with target as (
  select slug from venues where slug = 'koa-shala-spa-sanur' and status = 'active' and publication_status = 'published'
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Koa Shala Spa menu', 1, 'draft', 'partial', 'https://www.koashala.com/spa', 'Official Koa Shala Spa menu',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, 'd2bca942e8437f03062d9ae4501e45ebb0840f4a88bffa08aea3b13cea9044f8', 'spa'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'spa')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Massage 90 minute treatment', 0), ('+Plus treatments 30 minute', 1), ('Spa Rituals', 2), ('Yoga Package', 3)) as s(name, pos)
  returning id, name
