insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Massages', 'Full Body Massage (Balinese)', 'Enjoy 70 minutes of massage, using blends of essential oils from Indonesian spices and flowers. Our massage therapists incorporate a variety of techniques to relax every day muscular tensions, aches and pains. A planet away from the Bali beach massage – end with a warm shower.', 650000, 'IDR', 0), ('Massages', 'Exfoliation Massage (Mandi Lulur)', 'This treatment begins with a 65 minute Balinese massage, then the entire body is painted in a brown, granular paste (the traditional Javanese ‘lulur’) containing turmeric, sandalwood, cinnamon, and rice powder. The paste is then gently rubbed to exfoliate the skin. After a quick rinse, the body is covered in fresh yoghurt. The enzymes stimulate cell activity and restore the pH balance of the skin,', 800000, 'IDR', 1), ('Massages', 'Aromatherapy Massage', 'During this treatment, the subtle aromas from the essential oils help strengthen the body’s healing potential and deepen relaxation. Choose from a variety carefully crafted premium quality blends to suit your personal needs (headache & migraine, PMS, cold & flu etc). This treatment includes an aromatherapy bath.', 690000, 'IDR', 2), ('Massages', 'Magnesium Massage', 'A deeply restorative massage using high quality magnesium oil specifically formulated to enhance tissue recovery, ease muscle aches and inflammation, and improve tendon flexibility. Magnesium is a mineral that supports healthy muscle function, and is a favourite among those with physically active lifestyles. In order to allow the oil to have maximum benefit, we do not recommend a shower immediatel', 690000, 'IDR', 3), ('Massages', 'Hot Stone Massage', 'Hot stone therapy is a powerful massage technique that involves heated riverbed stones. The effects of this ancient form of healing have been proven to release tension in muscles, increase blood circulation, trigger relaxation response in the nervous system and restore fluidity to the connective tissue joints. You will find it a wonderful alternative to your normal massage schedule.', 690000, 'IDR', 4), ('Massages', 'Tension Release Massage', 'This massage combines Japanese Shiatsu palm pressing and pressure points along the energy meridian lines followed by a firm and deeply releasing oil massage to soothe sore and tired muscles.', 680000, 'IDR', 5), ('Massages', 'Thai Massage', 'A Thai massage is more energizing and rigorous than other classic forms of massage. It is also known as the Thai Yoga massage, as the therapist will use her hands, knees, legs and feet to guide you into a series of yoga-like stretches.', 680000, 'IDR', 6), ('Massages', 'Shiatsu Massage', 'A traditional Japanese finger pressure massage using slow, deep penetration of key points along the acupuncture meridians. The dispersing of excess or blocked energy can promote circulation to deficient areas of the body, stimulate the immune system and restore balance.', 680000, 'IDR', 7), ('Massages', 'Pregnancy Massage', 'This is a very gentle massage using side-lying pregnancy massage techniques. For the first trimester, we suggest using our non-scented oil only. As for the second and third trimester, we have a pregnancy safe aromatherapy oil designed to calm and release muscle tension.', 650000, 'IDR', 8), ('Massages', 'Slimming Massage', 'This treatment begins with a 20-minute full body anti-cellulite scrub enriched with green tea, ginkgo biloba, Japanese seaweed and bamboo micro beads. The scrub is buffed off the body with warm towels and a detox body mask and serum is applied. The body is then fully covered in sarongs to infuse while receiving a 10-minute scalp massage. The mask contains high antioxidant green tea extract and whi', 980000, 'IDR', 9), ('Massages', 'Flower Bath', 'Upgrade your massage with some flower power - includes a hot pot of tea and handful of dates to enjoy while you soak in the tub.', 215000, 'IDR', 10), ('Massages', 'Foot Massage', 'For a more gentle alternative to reflexology, enjoy our relaxing foot massage.', 320000, 'IDR', 11)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

