         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, 'eacb4fd3972a20f91fdb4d967b4a11fe9f49d3f086d87cbbd4ec9246e35e011f', 'food'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'food')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('OCEAN MEDLEY', 0), ('SUSHI AND SASHIMI', 1), ('MEAT & GRILL', 2), ('SHARING and pick your side', 3), ('SIDE', 4), ('RICE BOWL', 5), ('PIZZA', 6), ('PASTA', 7), ('TAPAS', 8), ('BURGER AND SANDWICHES', 9), ('STARTERS', 10), ('MAIN COURSES', 11), ('VEGETARIAN CORNER', 12), ('ASIAN STREET FOOD INSTAN NOODLES', 13), ('DESSERT', 14), ('EDAMAME', 15)) as s(name, pos)
  returning id, name
)
